// AC-01,06,07: FileStorage responsibility.
package com.foodrescue.backend.file.storage

import java.io.IOException
import java.io.InputStream

/** Bytes actually persisted, measured while writing. */
data class StoredObject(val sizeBytes: Long, val sha256Hex: String)

/**
 * Port for file bytes (roadmap D4). Keys are generated by the server; adapters must reject anything else.
 * Implementations throw [java.io.IOException] on storage failures and [java.nio.file.NoSuchFileException] for missing keys.
 */
interface FileStorage {
    @Throws(IOException::class) fun store(key: String, content: InputStream): StoredObject
    @Throws(IOException::class) fun open(key: String): InputStream
    @Throws(IOException::class) fun delete(key: String)
}
